return [{
  json: {
    title: 'Usage By Session',
    visualization: 'table or bar chart',
    sql: `SELECT session_id, COUNT(*) AS run_count, SUM(COALESCE(input_tokens, 0)) AS input_tokens, SUM(COALESCE(cached_input_tokens, 0)) AS cached_input_tokens, SUM(COALESCE(output_tokens, 0)) AS output_tokens, MAX(started_at) AS last_run_at FROM codex_runs WHERE session_id IS NOT NULL GROUP BY session_id ORDER BY last_run_at DESC LIMIT 100;`
  }
}];

return [{
  json: {
    title: 'Tokens By Model',
    visualization: 'stacked bar chart',
    sql: `SELECT COALESCE(model, 'unknown') AS model, COUNT(*) AS run_count, SUM(COALESCE(input_tokens, 0)) AS input_tokens, SUM(COALESCE(output_tokens, 0)) AS output_tokens FROM codex_runs GROUP BY COALESCE(model, 'unknown') ORDER BY input_tokens DESC;`
  }
}];

return [{
  json: {
    title: 'Failed Runs',
    visualization: 'data table',
    sql: `SELECT id, workflow_id, node_id, runtime, session_id, thread_id, error_message, started_at, ended_at FROM codex_runs WHERE status = 'failed' ORDER BY started_at DESC LIMIT 100;`
  }
}];

return [{
  json: {
    title: 'Recent Changed Files',
    visualization: 'data table',
    sql: `SELECT a.created_at, r.workflow_id, r.node_id, r.session_id, a.label, a.payload_json FROM codex_run_artifacts a INNER JOIN codex_runs r ON r.id = a.run_id WHERE a.kind = 'file_change' ORDER BY a.created_at DESC LIMIT 100;`
  }
}];

return [{
  json: {
    title: 'Recent Shell Commands',
    visualization: 'data table',
    sql: `SELECT a.created_at, r.workflow_id, r.node_id, r.session_id, a.label, a.payload_json FROM codex_run_artifacts a INNER JOIN codex_runs r ON r.id = a.run_id WHERE a.kind = 'command' ORDER BY a.created_at DESC LIMIT 100;`
  }
}];
